const account='tomas.kocner@wofevents.com';
const clean=(v,n)=>String(v??'').replace(/\s+/g,' ').trim().slice(0,n);
const stripHtml=v=>String(v??'').replace(/<!--[\s\S]*?-->/g,' ').replace(/<(script|style|head|svg)\b[^>]*>[\s\S]*?<\/\1>/gi,' ').replace(/<(br|p|div|li|tr|h[1-6])\b[^>]*>/gi,'\n').replace(/<[^>]+>/g,' ').replace(/&nbsp;/gi,' ').replace(/&amp;/gi,'&').replace(/&quot;/gi,'\"').replace(/&#(?:39|x27);/gi,"'").replace(/\s+/g,' ').trim();
const preview=json=>{const raw=json.textPlain||json.text||json.html||'';const value=/<(?:!doctype|html|body|table|div|p)\b/i.test(String(raw))?stripHtml(raw):clean(raw,2000);return clean(value,2000)||'HTML e-mail – celý obsah otvoríš v poštovej schránke.'};
const address=(from)=>{if(typeof from==='string')return clean(from,500);const first=from?.value?.[0];return clean(first?.name?first.name+' <'+first.address+'>':first?.address||from?.text,500)};
const unique=new Map();
for(const {json} of items){const messageId=clean(json.messageId||json.headers?.['message-id']||json.headers?.messageId,500);const rawDate=json.date||json.receivedDate||json.headers?.date;const date=new Date(rawDate);if(!messageId||Number.isNaN(date.getTime()))continue;unique.set(messageId,{json:{sourceAccount:account,messageId,providerUid:clean(json.uid||json.attributes?.uid,120),threadId:clean(json.threadId||messageId,500),subject:clean(json.subject||'(bez predmetu)',500),sender:address(json.from),timestamp:date.toISOString(),preview:preview(json),url:'',important:false}})}
return [...unique.values()];
